// 告警类型
interface AlarmItem {
  id: string
  deviceId: string
  deviceName: string
  district: string
  type: string
  content: string
  offlineTime: string
  duration: string
  alarmTime: string
  status: 'pending' | 'processing' | 'resolved'
  handler: string
}

// 告警类型映射
const alarmTypeMap: Record<string, { color: string; icon: React.ReactNode }> = {
  设备离线: { color: 'red', icon: <DesktopOutlined /> },
  心跳超时: { color: 'orange', icon: <ClockCircleOutlined /> },
  开门反馈异常: { color: 'blue', icon: <ExclamationCircleOutlined /> },
  格口故障: { color: 'red', icon: <WarningOutlined /> },
  温度异常: { color: 'orange', icon: <WarningOutlined /> },
  电源异常: { color: 'red', icon: <WarningOutlined /> }
}

// 告警状态映射
const alarmStatusMap: Record<string, { text: string; color: string }> = {
  pending: { text: '待处理', color: 'error' },
  processing: { text: '处理中', color: 'warning' },
  resolved: { text: '已处理', color: 'success' }
}

